83: func Load(path string) (*Result, error) {
84: 	v := viper.New()
85: 	v.SetEnvPrefix(EnvPrefix)
86: 	v.SetEnvKeyReplacer(strings.NewReplacer(".", "_"))
87: 	v.AutomaticEnv()
88: 
89: 	var cfg *Config
90: 
91: 	if path == "" {
92: 		cfg = Default()
93: 	} else {
94: 		cfg = &Config{}
95: 		file, err := getConfigFile(context.Background(), path)
96: 		if err != nil {
97: 			return nil, err
98: 		}
99: 		defer file.Close()
100: 		stat, err := file.Stat()
101: 		if err != nil {
102: 			return nil, err
103: 		}
104: 
105: 		// reimplement logic from v.ReadInConfig()
106: 		v.SetConfigFile(stat.Name())
107: 		ext := filepath.Ext(stat.Name())
108: 		if len(ext) > 1 {
109: 			ext = ext[1:]
110: 		}
111: 		if !slices.Contains(viper.SupportedExts, ext) {
112: 			return nil, viper.UnsupportedConfigError(ext)
113: 		}
114: 		if err := v.ReadConfig(file); err != nil {
115: 			return nil, err
116: 		}
117: 	}
118: 
119: 	var (
120: 		result      = &Result{Config: cfg}
121: 		deprecators []deprecator
122: 		defaulters  []defaulter
123: 		validators  []validator
124: 	)
125: 
126: 	f := func(field any) {
127: 		// for-each deprecator implementing field we collect
128: 		// them up and return them to be run before unmarshalling and before setting defaults.
129: 		if deprecator, ok := field.(deprecator); ok {
130: 			deprecators = append(deprecators, deprecator)
131: 		}
132: 
133: 		// for-each defaulter implementing fields we invoke
134: 		// setting any defaults during this prepare stage
135: 		// on the supplied viper.
136: 		if defaulter, ok := field.(defaulter); ok {
137: 			defaulters = append(defaulters, defaulter)
138: 		}
139: 
140: 		// for-each validator implementing field we collect
141: 		// them up and return them to be validated after
142: 		// unmarshalling.
143: 		if validator, ok := field.(validator); ok {
144: 			validators = append(validators, validator)
145: 		}
146: 	}
147: 
148: 	// invoke the field visitor on the root config firsts
149: 	root := reflect.ValueOf(cfg).Interface()
150: 	f(root)
151: 
152: 	// these are reflected config top-level types for fields where
153: 	// they have been marked as experimental and their associated
154: 	// flag has enabled set to false.
155: 	var skippedTypes []reflect.Type
156: 
157: 	val := reflect.ValueOf(cfg).Elem()
158: 	for i := 0; i < val.NumField(); i++ {
159: 		// search for all expected env vars since Viper cannot
160: 		// infer when doing Unmarshal + AutomaticEnv.
161: 		// see: https://github.com/spf13/viper/issues/761
162: 		structField := val.Type().Field(i)
163: 		if exp := structField.Tag.Get("experiment"); exp != "" {
164: 			// TODO(georgemac): register target for skipping
165: 			if !v.GetBool(fmt.Sprintf("experimental.%s.enabled", exp)) {
166: 				skippedTypes = append(skippedTypes, structField.Type)
167: 			}
168: 		}
169: 
170: 		key := fieldKey(structField)
171: 		bindEnvVars(v, getFliptEnvs(), []string{key}, structField.Type)
172: 
173: 		field := val.Field(i).Addr().Interface()
174: 		f(field)
175: 	}
176: 
177: 	// run any deprecations checks
178: 	for _, deprecator := range deprecators {
179: 		warnings := deprecator.deprecations(v)
180: 		for _, warning := range warnings {
181: 			result.Warnings = append(result.Warnings, warning.Message())
182: 		}
183: 	}
184: 
185: 	// run any defaulters
186: 	for _, defaulter := range defaulters {
187: 		if err := defaulter.setDefaults(v); err != nil {
188: 			return nil, err
189: 		}
190: 	}
191: 
192: 	if err := v.Unmarshal(cfg, viper.DecodeHook(
193: 		mapstructure.ComposeDecodeHookFunc(
194: 			append(DecodeHooks, experimentalFieldSkipHookFunc(skippedTypes...))...,
195: 		),
196: 	)); err != nil {
197: 		return nil, err
198: 	}
199: 
200: 	// run any validation steps
201: 	for _, validator := range validators {
202: 		if err := validator.validate(); err != nil {
203: 			return nil, err
204: 		}
205: 	}
206: 
207: 	return result, nil
208: }
